  /**
   * allProjectKubes iterates over GET /v1/cloud/project/{serviceName}/kube (List your managed Kubernetes clusters).
   *
   * It lists the IDs with {@link CloudApi.listProjectKubes}, then gets each object with
   * {@link CloudApi.getProjectKube}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action publicCloudProject:apiovh:kube/get.
   *
   * @param serviceName - Service name
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.CloudKubeCluster}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.cloud.allProjectKubes(serviceName)) console.log(item);
   */
  allProjectKubes(
    serviceName: string,
    options?: RequestOptions,
  ): AsyncIterable<models.CloudKubeCluster> {
    return this._each(
      () => this.listProjectKubes(serviceName, options),
      (listedId) => this.getProjectKube(serviceName, listedId, options),
    );
  }

