  /**
   * allProjectRegions iterates over GET /v1/cloud/project/{serviceName}/region (List your regions).
   *
   * It lists the IDs with {@link CloudApi.listProjectRegions}, then gets each object with
   * {@link CloudApi.getProjectRegion}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action publicCloudProject:apiovh:region/get.
   *
   * @param serviceName - Service name
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.CloudRegion}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.cloud.allProjectRegions(serviceName)) console.log(item);
   */
  allProjectRegions(
    serviceName: string,
    options?: RequestOptions,
  ): AsyncIterable<models.CloudRegion> {
    return this._each(
      () => this.listProjectRegions(serviceName, options),
      (listedId) => this.getProjectRegion(serviceName, listedId, options),
    );
  }

